-- 热更新
local rs = game:GetService("ReplicatedStorage")
local Rewire = require(rs.Packages.rewire)
local reloader = Rewire.HotReloader.new()
local WuKongClientCSharp = _G.wdm.WuKong.RbxClient.WuKongClient
local Env = require(game.ReplicatedStorage.Packages.DotEnv)
local HotReloadEvent = rs.WuKong:waitForChild("HotReloadEvent")

local module = {}
function throttle(func, event, delay)
	local lastCall = 0
	local executed = true
	local args = {}

	game["Run Service"].Heartbeat:Connect(function()
		if not executed and os.clock() - lastCall > delay then
			executed = true
			func(table.unpack(args))
			event:Fire()
		end
	end)

	return function(...)
		args = { ... }
		lastCall = os.clock()
		executed = false
	end
end

module.Watch = function(WuKong)
	local handler = function()
		warn("client reloading")
		local prevHost = WuKongClientCSharp.GetHost()
		if prevHost then
			prevHost:Dispose()
		end

		local success, result = pcall(function()
			WuKong._facade = WuKongClientCSharp.Start(Env.IsClientDev)
		end)

		if not success then
			warn(result)
		end
	end

	if game["Run Service"]:IsStudio() then
		local throttledFunction = throttle(handler, HotReloadEvent, 0.2) -- 0.2秒节流
		reloader:scan(rs._genConfigs, function() end, throttledFunction)
	end
end

return module
